# The delegations of the steward role made on a sheet, in the order they were made.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.delegation.RespondWithDelegations
  govern: [ readonly-transaction ]
# A steward delegates the steward role to a user for a from-date and a to-date, inclusive.
