package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import net.officefloor.hq.app.AsOf;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Loads the sheet. A read made as of a date (see {@link AsOf}) loads it as it stood at the end of
 * that date, the date standing in for its today; a change always loads it as it is now.
 */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository,
            HttpServletRequest request, Out<Sheet> sheetOut) throws SheetNotFoundException {
        Sheet sheet = repository.find(sheetId == null ? "" : sheetId.trim());
        if (sheet == null) throw new SheetNotFoundException(sheetId);
        LocalDate asOf = "GET".equals(request.getMethod()) ? AsOf.of(request) : null;
        sheetOut.set(asOf == null ? sheet : repository.asOf(sheet, asOf));
    }
}
package net.officefloor.hq.app.role;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetArchivedException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Refuses any change by a viewer, and any change at all on an archived sheet, before anything is
 * read or written. A viewer sees every screen and figure and can change nothing; an archived sheet
 * stays visible to everyone and no one can change it. Runs first on every change endpoint except the
 * bulk ones, which go through with every selected item refused.
 */
public class CheckCanChange {
    public void check(@PathVariable("sheetId") String sheetId, RoleRepository roles, SheetRepository sheets,
            HttpServletRequest request) throws ViewerException, SheetArchivedException {
        String id = sheetId == null ? "" : sheetId.trim();
        String user = Audit.user(request);
        if (Role.VIEWER.equals(roles.roleOf(id, user))) {
            throw new ViewerException("A viewer may not change the sheet");
        }
        if (sheets.isArchived(id)) throw new SheetArchivedException(id);
    }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useUser } from '../session/session';
import { DATE, delegationsKey, useDelegations } from './delegation';
import type { Delegation, DelegationChange } from './delegation';

// A steward delegates the steward role to a user for a from-date and a to-date, inclusive (blank from:
// the sheet's today; blank to: the from-date). While the sheet's today is inside the range the user acts
// as a steward in every rule. Anyone but a steward (by their own role) is refused, as is a to-date
// before the from-date. Every delegation made is listed below the form.
function Delegations({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const delegations = useDelegations(sheetId);
  const [fields, setFields] = useState<DelegationChange>({ user: '', from: '', to: '' });
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const save = useMutation({
    mutationFn: (body: DelegationChange) =>
      postJson<Delegation>(`/api/sheets/${encodeURIComponent(sheetId)}/delegations`, body, user),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: delegationsKey(sheetId) });
    },
    onError: () => setError('That delegation could not be made.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const name = fields.user.trim();
    const from = fields.from.trim();
    const to = fields.to.trim();
    if (name === '') {
      setError('A user name is required.');
      return;
    }
    for (const date of [from, to]) {
      if (date !== '' && (!DATE.test(date) || Number.isNaN(Date.parse(date)))) {
        setError('A date is yyyy-MM-dd, or blank.');
        return;
      }
    }
    if (from !== '' && to !== '' && to < from) {
      setError('A to-date is on or after the from-date.');
      return;
    }
    once((done) => save.mutate({ user: name, from, to }, { onSettled: done }));
  };

  const change = (next: Partial<DelegationChange>) => {
    setFields((f) => ({ ...f, ...next }));
    setError('');
  };

  return (
    <section data-testid="delegations">
      <h2>Delegations</h2>
      <form onSubmit={submit} data-testid="delegate-form">
        <label>
          User{' '}
          <input data-testid="delegate-user" value={fields.user} onChange={(e) => change({ user: e.target.value })} />
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="delegate-from"
            placeholder="today"
            value={fields.from}
            onChange={(e) => change({ from: e.target.value })}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            data-testid="delegate-to"
            placeholder="from-date"
            value={fields.to}
            onChange={(e) => change({ to: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="delegate-submit" disabled={save.isPending}>
          Delegate steward
        </button>
        {error && (
          <p role="alert" data-testid="delegate-error">
            {error}
          </p>
        )}
      </form>
      <ul data-testid="delegate-list">
        {(delegations.data ?? []).map((d) => (
          <li key={d.id} data-testid="delegate-line">
            <span data-testid="delegate-line-user">{d.user}</span> acts as steward from{' '}
            <span data-testid="delegate-line-from">{d.from}</span> to <span data-testid="delegate-line-to">{d.to}</span>{' '}
            for <span data-testid="delegate-line-by">{d.by}</span>
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: -7, Component: Delegations });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/**
 * The steward role delegated by a steward (`by`) to a user from a date to a date (yyyy-MM-dd), inclusive,
 * by the sheet's today: while today is inside the range the user acts as a steward.
 */
export type Delegation = { id: number; user: string; by: string; from: string; to: string };

/** A delegation as the screen sends it (a blank from-date: the sheet's today; a blank to-date: the from-date). */
export type DelegationChange = { user: string; from: string; to: string };

export const delegationsKey = (sheetId: string) => ['sheet', sheetId, 'delegations'] as const;

/** The delegations made on the sheet, in the order they were made. */
export function useDelegations(sheetId: string) {
  return useQuery({
    queryKey: delegationsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ delegations: Delegation[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/delegations`))
        .delegations,
  });
}

/** A from- or to-date as the screen takes it: blank, or a date yyyy-MM-dd. */
export const DATE = /^\d{4}-\d{2}-\d{2}$/;

