package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.CheckClaimPeriod;
import net.officefloor.hq.app.period.ClosedPeriodException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.CheckClaimRetired;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.hq.app.paste.PasteLine;
import net.officefloor.hq.app.paste.PasteLines;
import net.officefloor.hq.app.paste.PasteResponse;

/**
 * Adds a DRAFT claim per pasted line, in order, for the person on the sheet with that name (matched
 * as names are compared). Every line is checked first, as the claim form checks a claim (its person
 * on the sheet, its due-by outside a closed period and not after its person's retirement), so a
 * refused paste writes nothing; then each claim is saved, logged and audited as one added by the form.
 */
public class AddPastedClaims {
    public void add(@Val Sheet sheet, @Val PasteLines paste, PersonRepository people, ClaimRepository claims,
            PeriodRepository periods, RateRepository rates, SettingsRepository settings, ClaimLogRepository log,
            HttpServletRequest request, Audit audit, Out<PasteResponse> result)
            throws InvalidClaimException, ClosedPeriodException, RetiredPersonException {
        Settings terms = settings.find(sheet.id());
        List<Person> persons = new ArrayList<>();
        List<Claim> built = new ArrayList<>();
        for (PasteLine line : paste.lines()) {
            Person person = people.findByName(sheet.id(), line.name());
            if (person == null) throw new InvalidClaimException("No one named " + line.name() + " is on the sheet");
            LocalDate date = line.claim().date() == null ? terms.entryDay(sheet.today()) : line.claim().date();
            Claim claim = new Claim(null, sheet.id(), person.getId(), line.claim().amount(), date, line.claim().note(),
                    ClaimStatus.DRAFT, null, null, null);
            claim.setDueBy(date.plusDays(terms.termsFor(person, date)));
            new CheckClaimPeriod().check(sheet, claim, periods);
            claim.setLateEntry(periods.softClosedOn(sheet.id(), claim.getDueBy()) != null);
            new CheckClaimRetired().check(sheet, claim, people);
            persons.add(person);
            built.add(claim);
        }
        String user = Audit.user(request);
        for (int i = 0; i < built.size(); i++) {
            Claim claim = built.get(i);
            claims.save(claim);
            log.record(claim, user, sheet.today(), LogClaimStatus.due(sheet, claim, people, rates, settings));
            new AuditClaimAdded().audit(sheet, persons.get(i), claim, request, audit);
        }
        result.set(new PasteResponse(built.size()));
    }
}
package net.officefloor.hq.app.quick;

import java.time.LocalDate;
import net.officefloor.hq.app.period.ClosedPeriodException;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Refuses a quick-add while the due-by the claim would be fixed with (its date, the sheet's entry date
 * while it is set, else its today, plus its person's terms) is inside a closed period, before anything is written.
 */
public class CheckQuickAddPeriod {
    public void check(@Val Sheet sheet, @Val Person person, PeriodRepository periods, SettingsRepository settings)
            throws ClosedPeriodException {
        Settings terms = settings.find(sheet.id());
        LocalDate date = terms.entryDay(sheet.today());
        Period closed = periods.closedOn(sheet.id(), date.plusDays(terms.termsFor(person, date)));
        if (closed != null) throw new ClosedPeriodException(closed.name());
    }
}
handle:
  class: net.officefloor.hq.app.delegation.HandleInvalidDelegation
# Quick-add: a DRAFT claim for the named person, dated the sheet's entry date while it is set (else its today) with no note, adding the
# person (grade A) when the name is not on the sheet. One change: every rule is checked before
# anything is written, so a refusal leaves no new person behind. A bad name or amount is a 400.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.quick.ValidateQuickAdd
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: find
find:
  class: net.officefloor.hq.app.quick.FindQuickAddPerson
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.quick.CheckQuickAddPeriod
  govern: [ transaction ]
  next: retired
# A quick-add for a person retired before the claim's date is a 409 and writes nothing.
retired:
  class: net.officefloor.hq.app.quick.CheckQuickAddRetired
  govern: [ transaction ]
  next: savePerson
savePerson:
  class: net.officefloor.hq.app.quick.SaveQuickAddPerson
  govern: [ transaction ]
  next: build
build:
  class: net.officefloor.hq.app.claim.BuildClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: log
# The status it was saved at, with who, when and its due then.
log:
  class: net.officefloor.hq.app.claim.LogClaimStatus
